const body = $input.first().json.body || {};
const msg = body.message || {};
const call = msg.call || {};

// Real Vapi end-of-call-report puts startedAt/endedAt/duration/transcript at the TOP level of `message`,
// not nested under `message.call` (the spec doc's example payload was not accurate to the live schema).
// Fallbacks to call.* are kept in case a future Vapi version or a different event type nests them there.
const startedAt = msg.startedAt || call.startedAt || '';
const endedAt = msg.endedAt || call.endedAt || '';
const durationSeconds = msg.durationSeconds || call.durationSeconds || 0;
const transcript = msg.transcript || '';
const customerNumber = (call.customer && call.customer.number) || (msg.customer && msg.customer.number) || '';

return [{
  json: {
    call_id: call.id || msg.call?.id || '',
    transcript: transcript,
    started_at: startedAt,
    ended_at: endedAt,
    duration_seconds: durationSeconds,
    customer_number: customerNumber
  }
}];

