const raw = $input.first().json.content[0].text;
let cleaned = raw.trim();

// Strip markdown code fences using plain string ops (avoids regex+backtick transport issues)
const fence = String.fromCharCode(96, 96, 96); // ```
if (cleaned.startsWith(fence)) {
  let rest = cleaned.slice(fence.length);
  if (rest.toLowerCase().startsWith('json')) rest = rest.slice(4);
  const firstNewline = rest.indexOf(String.fromCharCode(10));
  if (firstNewline !== -1) rest = rest.slice(firstNewline + 1);
  if (rest.endsWith(fence)) rest = rest.slice(0, -fence.length);
  cleaned = rest.trim();
}

// Claude sometimes prefixes the JSON with a natural-language sentence (e.g. noting a
// call was cut short) even when told to return JSON only. Extract the JSON object by
// finding the first '{' and its balanced matching '}', ignoring any surrounding prose.
function extractJsonObject(text) {
  const start = text.indexOf('{');
  if (start === -1) return null;
  let depth = 0;
  for (let i = start; i < text.length; i++) {
    if (text[i] === '{') depth++;
    else if (text[i] === '}') {
      depth--;
      if (depth === 0) return text.slice(start, i + 1);
    }
  }
  return null;
}

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (firstErr) {
  const extracted = extractJsonObject(cleaned);
  if (!extracted) {
    throw new Error('Claude returned invalid JSON and no JSON object could be located: ' + firstErr.message + ' | raw: ' + cleaned.slice(0, 500));
  }
  try {
    parsed = JSON.parse(extracted);
  } catch (secondErr) {
    throw new Error('Claude returned invalid JSON even after extracting the object: ' + secondErr.message + ' | raw: ' + cleaned.slice(0, 500));
  }
}
return [{ json: parsed }];

const items = $input.all().filter(i => i.json && Object.keys(i.json).length > 0);
const match = items.length > 0 ? items[0].json : null;
return [{ json: {
  matched: items.length > 0,
  client_id: match ? match.id : null,
  owner_email: match ? (match.fields ? match.fields['Owner Email'] : match['Owner Email']) : null,
  ghl_contact_id: match ? (match.fields ? match.fields['GHL Contact ID'] : match['GHL Contact ID']) : null
} }];

const data = $input.first().json;
const company = (data.company_name || '').trim();
// Strip common legal suffixes so 'Acme Inc' and 'Acme' match the same
// client record - see docs/adr or session notes on the company-name
// matching fix. Used by both the Airtable Company Router formula and
// the Supabase client lookup (18c), so both branches match consistently.
const companyNormalized = company.toLowerCase().replace(/\s*[,.]?\s*(inc|llc|ltd|corp|co|company)\.?\s*$/, '').trim();
const processes = Array.isArray(data.processes) ? data.processes : [];
const hasAnySteps = processes.some(function(p) { return Array.isArray(p.steps) && p.steps.length > 0; });
const isLowQuality = !company || company.toLowerCase() === 'unknown' || processes.length === 0 || !hasAnySteps;

// One employee can now describe multiple processes in a single call. Every
// node downstream that used to read a single top-level process_name (Airtable
// status rows, Supabase call log, GHL notification emails) still needs ONE
// string to log/display, so compute a joined summary here rather than patching
// each consumer to branch on array length individually.
const processNames = processes.map(function(p) { return p.process_name; }).filter(Boolean);
const processSummary = processNames.length ? processNames.join(', ') : 'Unknown process';

return [{ json: { ...data, company_name: company, company_name_normalized: companyNormalized, process_name: processSummary, process_summary: processSummary, process_count: processes.length, _low_quality: isLowQuality, _quality_reason: isLowQuality ? ('Claude extraction produced insufficient data: company=' + JSON.stringify(company) + ', processes=' + processes.length) : null } }];

const NL = String.fromCharCode(10);
const data = $('8. Parse Claude JSON').item.json;

function esc(s) { return (s === null || s === undefined) ? '' : String(s); }

function renderSteps(steps) {
  return (steps || []).map(function(s) {
    const tools = (s.tools_used || []).join(', ') || 'None specified';
    const notes = [].concat(s.decision_points || [], s.pain_points || [], s.common_errors || []).map(function(x){ return typeof x === 'string' ? x : JSON.stringify(x); }).join('; ') || 'None';
    const done = s.completion_indicator || 'Not specified';
    const parts = [
      'Step ' + s.step_number + ': ' + esc(s.action || s.title),
      'Tools: ' + tools,
      'Notes: ' + notes,
      'Done when: ' + done
    ];
    return parts.join(NL);
  }).join(NL + NL);
}

function renderToolsList(process) {
  const toolsSet = new Set();
  (process.steps || []).forEach(function(s) { (s.tools_used || []).forEach(function(t) { toolsSet.add(t); }); });
  (process.tools_and_resources || []).forEach(function(t) { toolsSet.add(t); });
  return Array.from(toolsSet).join(', ') || 'None specified';
}

function renderExceptionHandling(process) {
  return (process.exception_handling || []).length
    ? process.exception_handling.map(function(e) {
        return typeof e === 'string' ? e : ('If ' + (e.if || e.condition) + ': ' + (e.then || e.action));
      }).join(NL)
    : 'None captured during this call.';
}

const processes = Array.isArray(data.processes) && data.processes.length ? data.processes : [{}];
const first = processes[0];
const extra = processes.slice(1);

const today = new Date().toISOString().slice(0, 10);

// Plain-text block for each additional process, appended to the doc after
// the template's own (first-process) section. Kept as plain text + simple
// line breaks since it's inserted via Google Docs insertText, not through
// the template's own formatting.
const extraSections = extra.map(function(p) {
  const lines = [];
  lines.push('');
  lines.push('----------------------------------------');
  lines.push('PROCESS: ' + esc(p.process_name));
  lines.push('----------------------------------------');
  if (p.department) lines.push('Department: ' + esc(p.department));
  if (p.process_owner) lines.push('Process owner: ' + esc(p.process_owner));
  if (p.role_summary) lines.push('Summary: ' + esc(p.role_summary));
  if (p.process_trigger) lines.push('Trigger: ' + esc(p.process_trigger));
  if (p.frequency) lines.push('Frequency: ' + esc(p.frequency));
  lines.push('');
  lines.push('Tools: ' + renderToolsList(p));
  lines.push('');
  lines.push('Steps:');
  lines.push(renderSteps(p.steps) || 'No steps captured.');
  lines.push('');
  lines.push('Exception handling:');
  lines.push(renderExceptionHandling(p));
  if (p.completion_criteria) {
    lines.push('');
    lines.push('Completion criteria: ' + esc(p.completion_criteria));
  }
  if (p.insider_notes || p.notes) {
    lines.push('');
    lines.push('Notes: ' + esc(p.insider_notes || p.notes));
  }
  return lines.join(NL);
}).join(NL);

return [{
  json: {
    doc_name: esc(data.employee_name) || 'Unnamed employee',
    process_count: processes.length,
    extra_sections_text: extraSections,
    tokens: {
      '{{COMPANY_NAME}}': esc(data.company_name),
      '{{PROCESS_NAME}}': esc(first.process_name),
      '{{EMPLOYEE_ROLE}}': esc(data.employee_role),
      '{{EMPLOYEE_NAME}}': esc(data.employee_name),
      '{{EMPLOYEE_TENURE}}': esc(data.employee_tenure),
      '{{DATE}}': today,
      '{{PROCESS_FREQUENCY}}': esc(first.frequency),
      '{{ROLE_SUMMARY}}': esc(first.role_summary),
      '{{PROCESS_TRIGGER}}': esc(first.process_trigger),
      '{{TOOLS_LIST}}': renderToolsList(first),
      '{{STEPS_BLOCK}}': renderSteps(first.steps) || 'No steps captured.',
      '{{EXCEPTION_HANDLING}}': renderExceptionHandling(first),
      '{{COMPLETION_CRITERIA}}': esc(first.completion_criteria),
      '{{INSIDER_NOTES}}': esc(first.insider_notes || first.notes)
    }
  }
}];

