// Same normalization as 8b.Validate Extraction Quality, applied here to
// existing Drive folder names too, so "Digital Dada" and "Digital Dada Inc"
// resolve to the same folder even though the folder itself keeps whatever
// name the FIRST caller from that company used.
function normalize(name) {
  return (name || '').toLowerCase().trim()
